<script>
  import {tick} from 'svelte';
  import {bindPhoneViewport} from './phoneViewport.mjs';
  import {deliveryKey,loadDelivery,prepareDelivery,reconcileDelivery} from './delivery.mjs';
  import {acquireBrowserSession} from './browserSession.mjs';
  import {buildWorldDraft} from '$lib/contracts/worldDraft.mjs';
  import AuthoringWorkbench from './AuthoringWorkbench.svelte';
  import MemoryStatus from './MemoryStatus.svelte';
  import CultureEditor from './CultureEditor.svelte';
  import DomainEditor from './DomainEditor.svelte';
  import DomainDetails from './DomainDetails.svelte';
  import CampaignControls from './CampaignControls.svelte';
  import {onMount} from 'svelte';
  import StoryView from '$lib/components/story/StoryView.svelte';
  let state=$state(null),selected=$state(null),tab=$state('Story'),error=$state(''),busy=$state(false);
  let search=$state(''),matches=$state([]),actor=$state(''),field=$state('name'),value=$state(''),run=$state(null),question=$state('healer'),decision=$state(null),assistantReply=$state(null);
  let decisionActor=$state('oren'),worldOpen=$state(false);
  let authorAnswer=$state(null),mobile=$state(false),libraryOpen=$state(false),keyboardOpen=$state(false),online=$state(true),connectionIssue=$state(false),pendingDelivery=$state(null),recoveredAction=$state(null),updateReady=$state(null);let applyingUpdate=false;
  let selectedContext=$state(null),contextMode=$state('searchable'),locationParent=$state(''),loreText=$state(''),loreScope=$state('self');
  let newLocation=$state(''),newHouse=$state(''),newController=$state(''),newAmount=$state(0),newUnit=$state('units');
  let sessionId=$state('browser_default'),campaignId=$state(''),campaignName=$state(''),campaignMode=$state('blank'),showCampaignCreate=$state(false);let viewEpoch=0;
  let newName=$state(''),newType=$state('house'),eventAccount=$state(''),eventField=$state('data.current.condition'),eventValue=$state(''),eventWitnessed=$state(false),eventReceipt=$state(null);
  let customAnswer=$state('');
  let commandText=$state('grep -n -F grain records/mira.md'),commandEvidence=$state(''),commandResult=$state(null);
  const operation=prefix=>prefix+'_'+crypto.randomUUID().replaceAll('-','');
  const label=id=>state?.records.find(r=>r.id===id)?.name||id||'None';
  const fields=record=>record?[['name',record.name],...Object.entries(record.data).flatMap(([key,item])=>item&&typeof item==='object'&&!Array.isArray(item)?Object.entries(item).map(([nested,entry])=>[`data.${key}.${nested}`,entry]):[[`data.${key}`,item]])]:[];
  const fieldLabel=key=>({locationId:'Location',roleTitle:'Role / title',condition:'Condition',allegianceHouseId:'Allegiance',birthId:'Birth House',currentId:'Current House',swornId:'Sworn House',parentIds:'Parents',originId:'Origin',species:'Species',kind:'Physical type',parentId:'Within',rulingHouseId:'Recognized ruling House',controllerHouseId:'Current controller',claims:'Political claims',controlHistory:'Control / occupation history',accessRights:'Access terms / provenance',accessHouseIds:'Houses with access',ownerHouseId:'Legal owner',acquisitions:'Knowledge acquisition',beliefProvenance:'Belief provenance',name:'Name'}[key.split('.').at(-1)]||key.split('.').at(-1));
  const fieldValue=()=>fields(selected?.record).find(([key])=>key===field)?.[1];
  async function api(body){const epoch=viewEpoch,headers={'Content-Type':'application/json','X-MythEngine-Session':sessionId,...(campaignId?{'X-MythEngine-Campaign':campaignId}:{})},response=await connectedFetch('/api/overhaul',{headers,...(body?{method:'POST',body:JSON.stringify(body)}:{})}),data=await response.json();if(!response.ok)throw Error(data.error||'Request failed');if(epoch!==viewEpoch)throw Object.assign(Error('Campaign changed while the response was in flight.'),{code:'STALE_VIEW'});return data;}
  async function connectedFetch(...args){try{const response=await fetch(...args);connectionIssue=false;return response;}catch(e){connectionIssue=true;throw Object.assign(Error('Connection interrupted. Drafts and the saved action remain on this device.'),{code:'NETWORK_UNAVAILABLE'});}}
  const pendingKey=()=>deliveryKey(sessionId,campaignId);
  function recoverSavedAction(){pendingDelivery=loadDelivery(localStorage,pendingKey());const saved=reconcileDelivery(pendingDelivery,state?.runs||[]);if(saved){run=saved;recoveredAction={id:saved.id,...saved.request};localStorage.removeItem(pendingKey());pendingDelivery=null;}}
  async function reconnect(){await refresh();recoverSavedAction();if(selected&&state.records.some(record=>record.id===selected.record.id))selected=await api({intent:'read',id:selected.record.id});}
  async function retryDelivery(){if(!pendingDelivery)return;run=await storyCommand({intent:'submit',turn:pendingDelivery});recoveredAction={id:run.id,...run.request};localStorage.removeItem(pendingKey());pendingDelivery=null;try{await refresh();await saveView();}catch(e){error=e.message;}}
  function applyUpdate(){if(!updateReady||busy||run?.status==='running'||pendingDelivery)return;applyingUpdate=true;updateReady.postMessage({type:'SKIP_WAITING'});}
  $effect(()=>{const opened=mobile&&(worldOpen||libraryOpen);if(!opened)return;const previous=document.activeElement;let panel;void tick().then(()=>{panel=document.querySelector(libraryOpen?'.library':'.inspector');panel?.querySelector('button,summary,input')?.focus();});const trap=event=>{if(event.key==='Escape'){worldOpen=false;libraryOpen=false;return;}if(event.key!=='Tab'||!panel)return;const nodes=[...panel.querySelectorAll('button:not(:disabled),summary,input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')].filter(el=>el.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}};document.addEventListener('keydown',trap);return()=>{document.removeEventListener('keydown',trap);if(previous?.getClientRects?.().length)previous.focus();else document.querySelector(".world-toggle")?.focus();};});
  let pendingJobs=0;
  async function guarded(work){error='';pendingJobs++;busy=true;try{return await work();}catch(e){if(e.code!=='STALE_VIEW')error=e.message;}finally{pendingJobs--;busy=pendingJobs>0;}}
  async function refresh(){const next=await api();state=next;campaignId=next.campaignId;if(run)run=state.runs.find(r=>r.id===run.id)||null;}
  async function saveView(){if(!state)return;await api({intent:'workspace',command:{intent:'view',view:{tab,selectedId:selected?.record.id||null,runId:run?.request?.action==='story'?run.id:null}}});}
  async function openCampaign(id){libraryOpen=false;worldOpen=false;recoveredAction=null;pendingDelivery=null;viewEpoch++;campaignId=id;selected=null;run=null;matches=[];decision=null;assistantReply=null;authorAnswer=null;commandResult=null;eventReceipt=null;actor='';decisionActor='';newLocation='';newHouse='';newController='';commandEvidence='';await api({intent:'workspace',command:{intent:'select',campaignId:id}});await refresh();decisionActor=state.records.find(r=>r.type==='character'&&r.id!==state.controls.record.data.playerId)?.id||'';commandText='grep -n -F '+JSON.stringify('oath')+' records/*.md';const saved=state.session.views[id];tab=saved?.tab||'Story';run=state.runs.find(r=>r.id===saved?.runId)||state.runs.find(r=>r.request?.action==='story'&&['running','paused'].includes(r.status))||state.runs.find(r=>r.request?.action==='story')||null;const recordId=saved?.selectedId||state.records.find(r=>r.type==='character')?.id||state.records.find(r=>r.type==='location')?.id;if(recordId&&state.records.some(r=>r.id===recordId))await select(recordId);recoverSavedAction();}
  async function createCampaign(){const result=await api({intent:'workspace',command:{intent:'create',operationId:operation('campaign'),name:campaignName,mode:campaignMode}});campaignName='';showCampaignCreate=false;await openCampaign(result.campaignId);}
  async function changeTab(item){worldOpen=false;libraryOpen=false;tab=item;if(item==='Story'&&state?.controls.record.data.preferences.focusMode)worldOpen=false;await saveView();}
  async function select(id){selected=await api({intent:'read',id});field='name';value=selected.record.name;contextMode=selected.record.gmContextMode||'searchable';locationParent=selected.record.data.geography?.parentId||'';selectedContext=selected.record.type==='location'?await api({intent:'locationContext',id}):null;eventField=selected.record.type==='character'?'data.current.condition':fields(selected.record).find(([key])=>key.startsWith('data.'))?.[0]||'';eventValue='';await saveView();}
  function chooseField(){const current=fieldValue();value=typeof current==='string'?current:JSON.stringify(current,null,2);}
  async function save(){const current=fieldValue();const parsed=typeof current==='string'?value:JSON.parse(value);await api({intent:'edit',edit:{id:selected.record.id,operationId:operation('edit'),expectedHash:selected.hash,patch:{[field]:parsed},evidenceIds:[]}});const id=selected.record.id;await refresh();await select(id);}
  async function saveDomain(patch,expectedHash=selected.hash){const id=selected.record.id,receipt=await api({intent:'edit',edit:{id,operationId:operation('domain'),expectedHash,patch,evidenceIds:[]}});await refresh();if(selected?.record.id===id)await select(id);return receipt;}
  async function undo(receipt){if(receipt.kind==='create-bundle'){await api({intent:'controls',command:{intent:'rollback',payload:{operationId:operation('rollback'),importOperationId:receipt.operationId}}});await refresh();return;}await api({intent:'undo',receiptId:receipt.operationId,undo:{operationId:operation('undo'),expectedHash:state.records.some(record=>record.id===receipt.recordId)?(await api({intent:'read',id:receipt.recordId})).hash:null}});await refresh();if(selected&&state.records.some(record=>record.id===selected.record.id))await select(selected.record.id);else if(selected){selected=null;await saveView();}}
  async function storyCommand(body){const epoch=viewEpoch,response=await connectedFetch('/api/turn',{method:'POST',headers:{'Content-Type':'application/json','X-MythEngine-Session':sessionId,'X-MythEngine-Campaign':campaignId},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(data.error);if(epoch!==viewEpoch)throw Object.assign(Error('Campaign changed while the response was in flight.'),{code:'STALE_VIEW'});return data;}
  async function readerEdit(payload){const result=await api({intent:'controls',command:{intent:'transcript',payload:{operationId:operation('reader'),...payload}}});await refresh();return result;}
  async function storyTurn(action){const capturedKey=pendingKey(),request=prepareDelivery(localStorage,capturedKey,{id:operation('story'),action:'story',...action});pendingDelivery=request;run=await storyCommand({intent:'submit',turn:request});localStorage.removeItem(capturedKey);pendingDelivery=null;try{await refresh();await saveView();}catch(e){error=e.message;}}
  async function turn(action){const text={treat:'The healer treats Mira’s hand.',hold:'Wait for more information.',conflict:'Consider the traveler’s conflicting account of Mira’s origin.',question:'Ask which intention Mira should consider next.',roll:'Roll a local court negotiation check.'}[action];run=await api({intent:'turn',turn:{id:operation('turn'),action,text}});await refresh();}
  let pollInFlight=false;
  async function poll(){if(pollInFlight||!online||connectionIssue)return;pollInFlight=true;try{if(run?.status==='running'){run=await api({intent:'run',id:run.id});await refresh();if(selected)selected=await api({intent:'read',id:selected.record.id});}}catch(e){if(e.code!=='STALE_VIEW')error=e.message;}finally{pollInFlight=false;}}
  async function stop(){run=run.request.action==='story'?await storyCommand({intent:'stop',id:run.id}):await api({intent:'stop',id:run.id});await refresh();}
  async function answer(choice){run=run.request.action==='story'?await storyCommand({intent:'answer',id:run.id,choice}):await api({intent:'answer',id:run.id,choice});await refresh();}
  async function resume(){run=run.request.action==='story'?await storyCommand({intent:'resume',id:run.id}):await api({intent:'turn',turn:run.request});await refresh();}

  async function createRecord(){
    const type=newType,id=operation(type),draft={id,type,name:newName};
    if(type==='location')draft.parentId=selected?.record.type==='location'?selected.record.id:null;
    if(type==='character'){draft.locationId=newLocation||null;draft.birthHouseId=newHouse||null;}
    if(type==='resource'){draft.locationId=newLocation;draft.ownerHouseId=newHouse||null;draft.controllerHouseId=newController||null;draft.amount=Number(newAmount);draft.unit=newUnit;}
    if(type==='faction')draft.houseId=newHouse||null;
    await api({intent:'create',create:{operationId:operation('create'),record:buildWorldDraft(draft)}});newName='';await refresh();await select(id);
  }
  async function setContext(){await api({intent:'edit',edit:{id:selected.record.id,operationId:operation('context'),expectedHash:selected.hash,patch:{gmContextMode:contextMode},evidenceIds:[]}});await refresh();await select(selected.record.id);}
  async function savePlace(){
    const args={locationId:selected.record.id,expectedVersion:selected.record.revision,parentLocationId:locationParent||null};
    if(loreText.trim())args.lore={title:'Author-established local lore',statement:loreText,locationLore:{version:1,category:'custom',scope:loreScope,origin:'campaign',salience:'situational',exceptionToFactIds:[]}};
    await api({intent:'saveLocation',save:{operationId:operation('location'),args}});loreText='';await refresh();await select(selected.record.id);
  }
  async function acceptEvent(){
    const current=fields(selected.record).find(([key])=>key===eventField)?.[1],value=typeof current==='string'?eventValue:JSON.parse(eventValue),id=operation('evt');
    const actorIds=selected.record.type==='character'?[selected.record.id]:[];
    eventReceipt=await api({intent:'ingestEvent',ingestion:{operationId:operation('accept'),expectedHashes:{[selected.record.id]:selected.hash},event:{schemaVersion:1,id,type:'event',name:'Accepted account: '+selected.record.name,revision:1,visibility:'secret',data:{body:eventAccount,actorIds,knownBy:eventWitnessed?actorIds:[],assertions:[{subjectId:selected.record.id,field:eventField,value,kind:eventField.startsWith('data.current.')?'event':'detail'}],worldTime:'Unspecified'}}}});
    await refresh();await select(selected.record.id);
  }
  async function runCommand(){commandResult=await api({intent:'sandboxCommand',command:{id:operation('command'),argv:['sh','-c',commandText],apply:true,evidenceIds:commandEvidence.split(',').map(id=>id.trim()).filter(Boolean)}});await refresh();if(selected)await select(selected.record.id);}
  onMount(()=>{let disposed=false,release;const media=matchMedia('(min-width:1100px)');mobile=!media.matches;worldOpen=media.matches;online=navigator.onLine;const viewportRelease=bindPhoneViewport({window,document,onChange:info=>keyboardOpen=info.keyboard});const layout=()=>{mobile=!media.matches;worldOpen=media.matches;libraryOpen=false;};const back=()=>{online=navigator.onLine;if(online&&state)void guarded(reconnect);};const off=()=>{online=false;};const visible=()=>{if(document.visibilityState==='visible')back();};addEventListener('online',back);addEventListener('offline',off);addEventListener('pageshow',back);document.addEventListener('visibilitychange',visible);let registration,installing;const inspectUpdate=()=>{if(!disposed&&registration?.waiting)updateReady=registration.waiting;};const updateFound=()=>{installing=registration.installing;installing?.addEventListener('statechange',inspectUpdate);};const changed=()=>{if(applyingUpdate)location.reload();};if('serviceWorker' in navigator){void navigator.serviceWorker.ready.then(value=>{if(disposed)return;registration=value;inspectUpdate();registration.addEventListener('updatefound',updateFound);});navigator.serviceWorker.addEventListener('controllerchange',changed);}media.addEventListener('change',layout);void guarded(async()=>{const claimed=await acquireBrowserSession({local:localStorage,tab:sessionStorage,locks:navigator.locks,randomId:()=>operation('browser')});if(disposed){claimed.release();return;}release=claimed.release;sessionId=claimed.id;await refresh();if(state.controls.record.data.preferences.focusMode)worldOpen=false;await openCampaign(state.campaignId);});const timer=setInterval(poll,350);return()=>{disposed=true;release?.();viewportRelease();removeEventListener('online',back);removeEventListener('offline',off);removeEventListener('pageshow',back);document.removeEventListener('visibilitychange',visible);registration?.removeEventListener('updatefound',updateFound);installing?.removeEventListener('statechange',inspectUpdate);navigator.serviceWorker?.removeEventListener('controllerchange',changed);clearInterval(timer);media.removeEventListener('change',layout);};});

</script>
<div class="workbench" class:chat-view={tab==='Story'} class:keyboard-open={keyboardOpen} class:focus={state?.controls.record.data.preferences.focusMode&&!worldOpen} style:--reading-font={(state?.controls.record.data.preferences.fontSize||17)+"px"}>
  <header><div class="brand"><span class="sigil">H</span><div><strong>Homer</strong><small>Your living epic</small></div></div><div class="isolation">Isolated workspace</div></header>
  {#if state}<div class="campaign-picker"><label for="campaign-select">Campaign</label><select id="campaign-select" value={campaignId} disabled={busy} onchange={event=>guarded(()=>openCampaign(event.currentTarget.value))}>{#each state.workspace.campaigns as campaign}<option value={campaign.id}>{campaign.id===campaignId?state.controls.record.name:campaign.name}</option>{/each}</select><button disabled={busy} onclick={()=>showCampaignCreate=!showCampaignCreate}>New campaign</button></div>{/if}
  {#if showCampaignCreate}<section class="campaign-create" aria-label="Create campaign"><label for="new-campaign-name">Campaign name</label><input id="new-campaign-name" bind:value={campaignName}/><label for="campaign-mode">Starting world</label><select id="campaign-mode" bind:value={campaignMode}><option value="blank">Blank world</option>{#if !state?.operatorSetup?.available}<option value="example">Ashford example (synthetic qualification)</option>{/if}</select><button disabled={busy||!campaignName.trim()} onclick={()=>guarded(createCampaign)}>Create campaign</button><button onclick={()=>showCampaignCreate=false}>Cancel</button></section>{/if}
  <nav aria-label="Workspace">{#each ['Story','World','Memory','Assistant','Controls'] as item}<button class:active={tab===item} onclick={()=>guarded(()=>changeTab(item))}>{item}</button>{/each}<button class="library-toggle" aria-expanded={libraryOpen} onclick={()=>{worldOpen=false;libraryOpen=!libraryOpen;}}>Files</button><span>Markdown is authoritative</span></nav>
  {#if !online||connectionIssue||pendingDelivery}<div class="connection-bar" role="status"><span>{!online?'Offline — keep writing your draft.':pendingDelivery?'Action delivery is not confirmed. Recover it before sending another.':'Connection interrupted. Your draft is kept.'}</span><button disabled={busy||!online} onclick={()=>guarded(pendingDelivery?retryDelivery:reconnect)}>{pendingDelivery?'Recover saved action':'Reconnect'}</button></div>{/if}
  {#if updateReady}<div class="connection-bar" role="status"><span>Homer update ready. Your draft stays on this device.</span><button disabled={busy||run?.status==='running'||!!pendingDelivery} onclick={applyUpdate}>Reload update</button></div>{/if}
  {#if error}<div role="alert" class="error">{error}</div>{/if}
  {#if !state}<p class="loading">Opening your story…</p>{:else}
  <div class="workspace" class:chat={tab==='Story'} class:world-open={worldOpen} class:library-open={libraryOpen}>
    {#if mobile&&(worldOpen||libraryOpen)}<button class="drawer-scrim" aria-label="Close world tools" onclick={()=>{worldOpen=false;libraryOpen=false;}}></button>{/if}
    <aside class="library" role={mobile&&libraryOpen?'dialog':undefined} aria-modal={mobile&&libraryOpen?true:undefined} aria-label="World files"><div class="rail-heading mobile-heading"><small>WORLD FILES</small><button onclick={()=>libraryOpen=false}>Close files</button></div><small>STORY LIBRARY</small><h2>{state.controls.record.name}</h2><p class="muted">Your linked medieval political fantasy world</p><div class="divider"></div><small>LINKED WORLD FILES</small>{#each ['character','house','location','resource','event','faction','chapter','asset','culture'] as type}<details open={type==='character'||type==='location'}><summary>{type[0].toUpperCase()+type.slice(1)}s</summary>{#each state.records.filter(r=>r.type===type) as record}<button class:selected={selected?.record.id===record.id} onclick={()=>guarded(async()=>{await select(record.id);libraryOpen=false;if(mobile)worldOpen=true;})}>{record.name}<span>r{record.revision}</span></button>{/each}</details>{/each}</aside>
    <main inert={mobile&&(worldOpen||libraryOpen)}>
      {#if tab==='Story'}
      {#key campaignId}<StoryView campaignId={campaignId} {sessionId} {recoveredAction} deliveryPending={!!pendingDelivery} connected={online&&!connectionIssue} title={state.controls.record.name} {worldOpen} onworld={()=>worldOpen=!worldOpen} transcriptControls={state.transcriptControls} onreaderedit={payload=>guarded(()=>readerEdit(payload))} campaign={state.controls.record.data} records={state.records} runs={state.runs} {run} {busy} onturn={storyTurn} onstop={()=>guarded(stop)} onresume={()=>guarded(resume)} oninspect={id=>guarded(async()=>{await select(id);worldOpen=true;})} onanswer={choice=>guarded(()=>answer(choice))} ondismiss={()=>guarded(async()=>{run=await api({intent:'dismiss',id:run.id});await refresh();})}/>{/key}
      {:else if tab==='Controls'}
      {#key campaignId}<CampaignControls {busy} {state} {api} {refresh} {guarded}/>{/key}
      {:else if tab==='World'}
      <div class="eyebrow">Story and world management</div><h1>World records</h1><p class="intro">Open linked files, edit one field, and restore an accepted revision.</p><section><h2>Create a world record</h2><label for="new-type">Record type</label><select id="new-type" bind:value={newType}><option value="house">House</option><option value="culture">Culture</option><option value="location">Location</option><option value="character">Character</option><option value="resource">Resource</option><option value="faction">Faction</option></select><label for="new-name">Name</label><input id="new-name" bind:value={newName}/>{#if newType==='character'||newType==='resource'}<label for="new-location">Location</label><select id="new-location" bind:value={newLocation}><option value="">{newType==='resource'?'Choose a location':'Unspecified'}</option>{#each state.records.filter(r=>r.type==='location') as location}<option value={location.id}>{location.name}</option>{/each}</select>{/if}{#if ['character','resource','faction'].includes(newType)}<label for="new-house">{newType==='character'?'Birth House':newType==='resource'?'Legal owner':'Linked House'}</label><select id="new-house" bind:value={newHouse}><option value="">Unspecified</option>{#each state.records.filter(r=>r.type==='house') as house}<option value={house.id}>{house.name}</option>{/each}</select>{/if}{#if newType==='resource'}<label for="new-controller">Current controller</label><select id="new-controller" bind:value={newController}><option value="">Unspecified</option>{#each state.records.filter(r=>r.type==='house') as house}<option value={house.id}>{house.name}</option>{/each}</select><label for="new-amount">Amount</label><input id="new-amount" type="number" min="0" bind:value={newAmount}/><label for="new-unit">Unit</label><input id="new-unit" bind:value={newUnit}/>{/if}<button disabled={busy||!newName.trim()||(newType==='resource'&&(!newLocation||!newUnit.trim()))} onclick={()=>guarded(createRecord)}>Create linked record</button></section>
      <section><h2>Location map</h2><div class="map">{#each state.records.filter(r=>r.type==='location') as location}<div><button onclick={()=>guarded(()=>select(location.id))}>{location.name}</button><span> {location.data.geography.parentId?'within '+label(location.data.geography.parentId):'root continent'} · {location.data.geography.kind}</span><small>Recognized ruler: {label(location.data.politics.rulingHouseId)} · Actual controller: {label(location.data.politics.controllerHouseId)}</small></div>{/each}</div></section>
      <section><h2>Accepted edits and conflicts</h2>{#if !state.history.length}<p class="muted">No accepted edits yet.</p>{/if}{#each state.history.slice().reverse() as receipt}<div class="receipt"><div><strong>{label(receipt.recordId)}</strong><p>{receipt.status} · {receipt.fields?.join(', ')||receipt.field||receipt.undoOf}</p></div>{#if receipt.status==='applied'&&(receipt.beforeHash||receipt.kind==='create'||receipt.kind==='create-bundle')}<button disabled={busy||run?.status==='running'||(receipt.kind!=='create-bundle'&&(state.records.find(record=>record.id===receipt.recordId)?.hash||null)!==receipt.afterHash)} onclick={()=>guarded(()=>undo(receipt))}>Undo</button>{:else}<span class="conflict">Canon preserved</span>{/if}</div>{/each}</section>
      {:else if tab==='Memory'}
      <MemoryStatus status={state.memoryStatus} {api} {guarded} {busy}/>
      <div class="eyebrow">Search and actor knowledge</div><h1>Find the source</h1><p class="intro">Literal search with file, line, and hash. NPC searches use only that actor’s view.</p><section><label for="actor">Knowledge scope</label><select id="actor" bind:value={actor}><option value="">GM / author</option>{#each state.records.filter(r=>r.type==='character') as character}<option value={character.id}>{character.name}</option>{/each}</select><label for="search">Search Markdown</label><div class="search"><input id="search" bind:value={search} placeholder="healer, oath, sealed letter…"/><button disabled={busy||!search.trim()} onclick={()=>guarded(async()=>matches=(await api({intent:'search',query:search,actorId:actor||undefined})).matches)}>Search</button></div>{#each matches as match}<button class="match" onclick={()=>guarded(()=>select(match.id))}><strong>{match.name}</strong><code>{match.path}:{match.line}</code><span>{match.text}</span></button>{/each}<p class="muted">{matches.length} matches. {state.status.memory}</p></section>
      {:else if tab==='Assistant'}
      {#key campaignId}<AuthoringWorkbench {api} {guarded} {refresh} {state} {campaignId} {busy} onopen={select}/>{/key}
      <details><summary>NPC decisions</summary><label for="question">NPC decision question</label><input id="question" bind:value={question}/><label for="decision-actor">NPC subject</label><select id="decision-actor" bind:value={decisionActor}>{#each state.records.filter(r=>r.type==='character'&&r.id!==state.controls.record.data.playerId) as npc}<option value={npc.id}>{npc.name}</option>{/each}</select><button disabled={busy||!question.trim()||!decisionActor} onclick={()=>guarded(async()=>decision=await api({intent:'decision',actorId:decisionActor,question}))}>Ask NPC decision</button>{#if decision}<h2>Intent: {decision.selected}</h2><p>{decision.options.find(o=>o.id===decision.selected)?.intent}</p><p class="muted">{decision.consequence}</p>{/if}</details>
      {/if}
      {#if tab==='Assistant'}<details class='activity'><summary>GM campaign tools</summary><p class='muted'>Commands run inside this campaign's isolated workspace. Supported file changes publish through the same validated writer.</p><label for='campaign-command'>Campaign command</label><textarea id='campaign-command' bind:value={commandText} rows='3'></textarea><label for='command-evidence'>Accepted source IDs for file changes</label><input id='command-evidence' bind:value={commandEvidence}/><button disabled={busy||!commandText.trim()} onclick={()=>guarded(runCommand)}>Run campaign tool</button>{#if commandResult}<pre>{commandResult.output?.stdout||commandResult.output?.stderr||'Completed'}</pre><p>Session {commandResult.id} · {commandResult.receipts?.length||0} validated changes</p>{/if}</details>{/if}
    </main>
    <aside class="inspector" role={mobile&&worldOpen?'dialog':undefined} aria-modal={mobile&&worldOpen?true:undefined} aria-label="World inspector"><div class="rail-heading"><small>WORLD & AGENTS</small><button class="close-world" onclick={()=>worldOpen=false}>Close panel</button></div>{#if tab==='Story'}{#if run}<details class="activity"><summary>Agent activity · {run.status}</summary><p class="muted">{run.requests} requests · {run.toolCalls} tools · 0 paid calls</p>{#each run.activity as entry,index}<div><span>{index+1}</span><code>{entry.name||entry.kind}</code><span>{entry.summary||entry.state}</span></div>{/each}{#if run.decision}<p class="muted">{label(run.decision.actorId)}: {run.decision.options.find(option=>option.id===run.decision.selected)?.intent}. {run.decision.consequence}</p>{/if}</details>{/if}{/if}<small>LINKED FILE</small>{#if selected}<h2>{selected.record.name}</h2><p class="muted">{selected.path} · revision {selected.record.revision}</p>{#if selected.record.type==='character'}<div class="condition">{selected.record.data.current.condition}</div>{/if}<DomainDetails record={selected.record} records={state.records} onopen={id=>guarded(()=>select(id))}/><DomainEditor record={selected.record} sourceHash={selected.hash} records={state.records} {busy} onsave={(patch,expectedHash)=>guarded(()=>saveDomain(patch,expectedHash))}/>
      <CultureEditor record={selected.record} sourceHash={selected.hash} {busy} onsave={saveDomain}/><details open={tab!=='Story'}><summary>Read record</summary>{#each Object.entries(selected.record.data) as [key,item]}<div class="record-section"><h3>{key[0].toUpperCase()+key.slice(1)}</h3>{#if typeof item==='string'}<p>{item}</p>{:else if Array.isArray(item)}{#each item as entry}<p>{typeof entry==='string'?entry:entry.text||entry.bond||(label(entry.subjectId)+' · '+fieldLabel(entry.field||'')+': '+JSON.stringify(entry.value))}</p>{/each}{:else}{#each Object.entries(item) as [key,value]}<div class="field"><span>{fieldLabel(key)}</span><strong>{Array.isArray(value)?value.map(label).join(', '):key.endsWith('Id')?label(value):value||'None'}</strong>{#if typeof value==='string'&&state.records.some(r=>r.id===value)}<button aria-label={'Open '+label(value)} onclick={()=>guarded(()=>select(value))}>↗</button>{/if}</div>{/each}{/if}</div>{/each}</details><details><summary>GM context</summary><label for="context-mode">Include this file</label><select id="context-mode" bind:value={contextMode}><option value="pinned">Pinned — full source</option><option value="partial">Partial — bounded excerpt</option><option value="searchable">Searchable — retrieve when useful</option></select><button disabled={busy} onclick={()=>guarded(setContext)}>Save context choice</button></details>
      {#if selected.record.type==='location'}<details><summary>Containment and inherited lore</summary><p class='muted'>{selectedContext?.chain.map(place=>place.name).join(' → ')}</p><label for='within'>Within</label><select id='within' bind:value={locationParent}><option value=''>Root place</option>{#each state.records.filter(r=>r.type==='location'&&r.id!==selected.record.id) as place}<option value={place.id}>{place.name}</option>{/each}</select><label for='lore'>Add local lore</label><textarea id='lore' bind:value={loreText} rows='3'></textarea><select aria-label='Lore scope' bind:value={loreScope}><option value='self'>This place</option><option value='descendants'>This place and sublocations</option></select><button disabled={busy} onclick={()=>guarded(savePlace)}>Save location</button>{#each selectedContext?.facts||[] as fact}<p>{fact.statement} {fact.inherited?'(inherited)':''}</p>{/each}</details>{/if}
      <details><summary>Accept a source account</summary><p class='muted'>Establish an account, then the GM applies its supported update automatically. Conflicting identity remains recorded for review.</p><label for='account'>What is established</label><textarea id='account' bind:value={eventAccount} rows='3'></textarea><label for='assertion-field'>Supported field</label><select id='assertion-field' bind:value={eventField}>{#each fields(selected.record).filter(([key])=>key.startsWith('data.')) as [key]}<option value={key}>{fieldLabel(key)}</option>{/each}</select><label for='assertion-value'>Established value</label><textarea id='assertion-value' bind:value={eventValue} rows='2'></textarea>{#if selected.record.type==='character'}<label><input type='checkbox' bind:checked={eventWitnessed}/> Known to this character</label>{/if}<button disabled={busy||!eventAccount.trim()||!eventValue.trim()} onclick={()=>guarded(acceptEvent)}>Accept account and update</button>{#if eventReceipt}<p>{eventReceipt.receipts.map(receipt=>receipt.status).join(', ')}</p>{/if}</details>
      <details class="editor"><summary>Edit one field</summary><p class="muted">Author edits are validated, version checked, and reversible.</p><label for="field">Field</label><select id="field" bind:value={field} onchange={chooseField}>{#each fields(selected.record) as [key]}<option value={key}>{fieldLabel(key)}</option>{/each}</select><label for="value">Value</label><textarea id="value" bind:value rows="5"></textarea><button class="primary" disabled={busy||run?.status==='running'} onclick={()=>guarded(save)}>Save field</button></details><details><summary>Markdown source</summary><pre>{selected.markdown}</pre></details>{/if}</aside>
  </div>
  <footer class:hidden-in-chat={tab==='Story'}><span>Plot Director retired in this runtime</span><span>{state.records.length} authoritative files · projection {state.projection.version.slice(0,10)}</span><span>Production data not mounted</span></footer>
  {/if}
</div>
