 .campaign-picker{display:flex;align-items:center;gap:10px;padding:8px 22px;background:#112221}.campaign-picker label{margin:0;font-size:12px}.campaign-picker select{width:min(280px,45vw);margin:0}.campaign-create{position:relative;margin:12px 22px;max-width:500px}.campaign-create input,.campaign-create select{max-width:100%}

  .workbench{min-height:100vh;background:#101510;color:#eeece4;font:14px/1.55 'Segoe UI',sans-serif}header{padding:22px 32px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #354035}.brand{display:flex;gap:14px;align-items:center}.brand strong{font:25px Georgia,serif}.brand small{display:block;color:#92998a}.sigil{border:1px solid #b79860;color:#c6a66c;font:28px Georgia;padding:2px 12px;border-radius:7px}.isolation{color:#a6b598;border:1px solid #354035;border-radius:20px;padding:7px 13px;font-size:12px}nav{display:flex;gap:6px;padding:12px 32px;background:#191e18;border-bottom:1px solid #354035}nav span{margin-left:auto;align-self:center;font-size:12px;color:#92998a}button,input,select,textarea{font:inherit;border-radius:6px}button{border:1px solid #354035;background:#20271f;color:#dcded3;padding:8px 12px;cursor:pointer}button:hover{border-color:#b79860;color:#f0d078}button:disabled{opacity:.4;cursor:default}button.active,.primary{background:#c6a66c;color:#101310;border-color:#c6a66c}.workspace{display:grid;grid-template-columns:220px minmax(350px,1fr) 360px;max-width:1700px;margin:auto}.library,.inspector{padding:25px 20px;background:#141a14}.library{border-right:1px solid #354035}.inspector{border-left:1px solid #354035;overflow-wrap:anywhere}small,.eyebrow{color:#a6b598;letter-spacing:.04em;font-size:11px}.library h2{margin:8px 0}.muted{color:#92998a;font-size:12px}.divider{border-top:1px solid #354035;margin:20px 0}summary{cursor:pointer;color:#bec2b6;padding:9px 0}.library button{display:flex;justify-content:space-between;text-align:left;width:100%;background:none;border-color:transparent;padding:6px 8px;font-size:12px}.library button.selected{background:#283027;color:#f0d078}.library button span{color:#92998a;font-size:10px}main{padding:32px 34px;min-width:0}h1{font:35px/1.2 Georgia,serif;color:#eeece4;margin:10px 0 18px}h2{font:21px Georgia,serif;margin:0 0 12px}h3{font-size:12px;color:#c6a66c;margin:0 0 7px}p{margin:0 0 14px}.intro{color:#bec2b6;margin-bottom:28px}section{border:1px solid #354035;border-radius:10px;background:#191e18;padding:20px;margin-bottom:20px}.actions{display:flex;gap:8px;flex-wrap:wrap}.activity{border:1px solid #354035;border-radius:8px;padding:5px 16px}.activity div{display:flex;gap:14px;font-size:12px;padding:5px 0}.activity code{color:#c6a66c}.record-section{padding:13px 0;border-top:1px solid #283027;font-size:12px}.record-section p{white-space:pre-wrap}.field{display:flex;gap:8px;align-items:center;margin:6px 0}.field span{color:#92998a;font-size:11px;min-width:87px}.field strong{font-weight:400}.field button{margin-left:auto;padding:0 7px}.condition{border:1px solid #3d4f3b;color:#a6b598;padding:6px 10px;border-radius:7px;margin:14px 0}label{display:block;color:#bec2b6;font-size:12px;margin:12px 0 6px}input,select,textarea{width:100%;color:#eeece4;background:#101510;border:1px solid #354035;padding:9px}.editor button{margin-top:8px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;color:#bec2b6}.search{display:flex;gap:8px}.search input{flex:1}.match{display:flex;flex-direction:column;text-align:left;gap:3px;width:100%;margin-top:12px}.match code{color:#a6b598;font-size:11px}.match span{font-size:12px}.map div{padding:12px 0;border-bottom:1px solid #283027}.map small{display:block;margin-top:6px}.map span{font-size:12px;color:#92998a}.receipt{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 0;border-top:1px solid #283027}.receipt p{font-size:12px;color:#92998a;margin:2px 0}.conflict{color:#c6a66c;font-size:11px}.error{background:#2d1820;color:#ecbec8;padding:12px 25px;overflow-wrap:anywhere}.loading{padding:40px}footer{display:flex;justify-content:space-between;gap:16px;border-top:1px solid #354035;padding:12px 32px;color:#92998a;font-size:11px}@media(max-width:1100px){.workspace{grid-template-columns:185px 1fr}.inspector{grid-column:1/-1;border-top:1px solid #354035}main{padding:25px}.inspector details{