.focus .library,.focus .inspector{display:none}.focus .workspace{grid-template-columns:1fr}.workbench :global(.story-reader .narration){font-size:var(--reading-font,17px)}.workbench.chat-view{height:100dvh;min-height:0;display:flex;flex-direction:column;overflow:hidden}.chat-view>header,.chat-view>nav,.chat-view>.campaign-picker,.chat-view>.campaign-create{flex-shrink:0}.chat-view>header{padding:14px 24px}.chat-view>nav{padding:9px 24px}.workspace.chat{position:relative;display:grid;flex:1;width:100%;min-height:0;grid-template-columns:200px minmax(0,1fr) 310px}.chat main{padding:0;min-height:0;overflow:hidden}.chat .library,.chat .inspector{min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:20px 16px}.chat:not(.world-open) .library,.chat:not(.world-open) .inspector{display:none}.chat:not(.world-open){grid-template-columns:minmax(0,1fr)}.rail-heading{display:flex;gap:10px;justify-content:space-between;align-items:center;margin-bottom:16px}.close-world{font-size:10px;padding:4px 7px}.inspector .activity{margin:0 0 22px;overflow-wrap:anywhere}.inspector .activity div{flex-wrap:wrap}.hidden-in-chat{display:none}@media(max-width:1100px){.workspace.chat{grid-template-columns:minmax(0,1fr)}.chat .library{display:none}.chat.world-open .inspector{display:block;position:absolute;right:0;top:0;bottom:0;width:min(360px,100vw);box-sizing:border-box;z-index:20;background:#141a14;box-shadow:-15px 0 35px #0008;border-left:1px solid #46543e}.chat-view>header{padding:12px 16px}.chat-view>nav{padding:8px 12px}}@media(max-width:650px){.chat-view>header{padding:10px 13px}.chat-view .brand small{font-size:10px}.chat-view .isolation{font-size:10px;padding:5px 8px;max-width:92px}.chat-view>nav{flex-wrap:nowrap;gap:4px;padding:7px 10px;overflow-x:auto}.chat-view>nav button{font-size:11px;padding:7px 9px;white-space:nowrap}.chat.world-open .inspector{top:0;width:100vw}.chat .inspector details{max-width:none}.chat-view .sigil{font-size:22px;padding:1px 8px}}

 .workbench{position:fixed;left:0;right:0;top:var(--homer-viewport-top,0px);height:var(--homer-viewport-height,100dvh);min-height:0;box-sizing:border-box;display:flex;flex-direction:column;overflow:hidden;padding-top:env(safe-area-inset-top,0px);padding-left:env(safe-area-inset-left,0px);padding-right:env(safe-area-inset-right,0px)}.workbench.chat-view{height:var(--homer-viewport-height,100dvh)}.workbench>header,.workbench>nav,.campaign-picker,.campaign-create,.connection-bar,.error,footer{flex-shrink:0}.workspace{position:relative;flex:1;width:100%;min-height:0;overflow:hidden}.workspace main,.workspace .library,.workspace .inspector{min-height:0;overflow:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch}.workspace.chat main{overflow:hidden}.library-toggle,.mobile-heading,.drawer-scrim{display:none}.connection-bar{display:flex;gap:12px;align-items:center;justify-content:space-between;padding:8px 14px;background:#283027;font-size:12px}.connection-bar span{min-width:0}.connection-bar button{flex-shrink:0;min-height:44px}.workbench :global(button),.workbench :global(summary){touch-action:manipulation}.workbench :global(:focus-visible){outline:2px solid #d4b56f;outline-offset:3px}
 @media(max-width:1099px){.library-toggle{display:block;min-height:44px}.workspace>.library,.workspace>.inspector{display:none}.workspace{grid-template-columns:minmax(0,1fr)}.workspace.library-open>.library,.workspace.world-open>.inspector{display:block;position:absolute;right:0;top:0;bottom:0;width:min(420px,100%);z-index:20;box-sizing:border-box;padding:16px 18px max(18px,env(safe-area-inset-bottom,0px));background:#141a14;box-shadow:-15px 0 35px #0008}.workspace.library-open .library details{display:block;width:100%}.mobile-heading{display:flex}.drawer-scrim{display:block;position:absolute;inset:0;z-index:19;background:#0008;border:0;border-radius:0}.workspace>main{grid-column:1}.rail-heading{position:sticky;top:-16px;background:#141a14;padding:8px 0;z-index:2}.rail-heading button{min-height:44px;font-size:12px}.workbench :global(button),.workbench :global(summary){min-height:44px}.workbench :global(input:not([type=checkbox])),.workbench :global(select),.workbench :global(textarea){font-size:16px;min-width:0}.workbench .campaign-picker{padding:6px 12px;gap:8px}.campaign-picker label{display:none}.campaign-picker select{flex:1;width:0}.campaign-picker button{font-size:12px}.workbench .library button{padding:9px 8px}.workbench>nav{overflow:auto;flex-wrap:nowrap;padding:6px 10px;gap:4px}.workbench>nav button{flex:1;min-width:0;font-size:11px;padding:8px 6px}.workbench>nav span{display:none}.workbench .workspace.chat.world-open .inspector{width:min(420px,100%)}.workbench.keyboard-open.chat-view>header,.workbench.keyboard-open.chat-view>nav,.workbench.keyboard-open.chat-view>.campaign-picker{display:none}.workbench.keyboard-open.chat-view .connection-bar{padding:4px 10px}.workbench.keyboard-open.chat-view .connection-bar span{font-size:11px}.workbench footer{padding-bottom:max(12px,env(safe-area-inset-bottom,0px))}}
 @media(max-width:650px){.workspace.world-open>.inspector,.workspace.library-open>.library,.workbench .workspace.chat.world-open .inspector{width:100%}.workbench>header{padding:8px 12px}.brand{gap:9px}.brand small{display:none}.isolation{font-size:10px;padding:4px 6px}.connection-bar{gap:8px}.connection-bar button{font-size:12px;max-width:120px}.workspace:not(.chat)>main{padding:18px 14px}.campaign-create{margin:8px 12px;max-height:50%;overflow:auto}}

@media(max-height:520px) and (max-width:1099px){.workbench>header{display:none}.workbench .campaign-picker{padding:3px 10px}.workbench>nav{padding:3px 8px}}
